# Generated by build.py from recipe.yml for recipe smtp-check-an-app-sent-the-right-mail. Do not edit.
set -e
cd "$(dirname "$0")"
cat > reset.eml <<'EOF'
From: app@example.com
To: ann@example.com
Subject: Reset your password

Someone asked to reset the password for ann@example.com.
Open this link to choose a new one:
https://app.example.com/reset/4f9c2a7e
EOF
cat > local-link.eml <<'EOF'
From: app@example.com
To: carol@example.com
Subject: Reset your password

Someone asked to reset the password for carol@example.com.
Open this link to choose a new one:
http://localhost:5000/reset/9b03d6e1
EOF
cat > wrong-to.eml <<'EOF'
From: app@example.com
To: dave@example.com
Subject: Reset your password

Someone asked to reset the password for dave@example.com.
Open this link to choose a new one:
https://app.example.com/reset/c71e0a52
EOF
surl --mail-delivered-to --mail-domain example.com --mailbox app@example.com:apppass --mailbox ann@example.com:annpass --mailbox bob@example.com:bobpass --mailbox carol@example.com:carolpass --mailbox dave@example.com:davepass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com -T reset.eml smtp://127.0.0.1:8080/app.example.com --next -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt carol@example.com -T local-link.eml smtp://127.0.0.1:8080/app.example.com --next -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt bob@example.com -T wrong-to.eml smtp://127.0.0.1:8080/app.example.com
curl -sS -o /dev/null --retry 10 --retry-all-errors --retry-delay 1 -u carol@example.com:carolpass -X "FETCH 1 FLAGS" imap://127.0.0.1:8081/INBOX --next -sS -o /dev/null --retry 10 --retry-all-errors --retry-delay 1 -u bob@example.com:bobpass -X "FETCH 1 FLAGS" imap://127.0.0.1:8081/INBOX
curl -sS --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=HEADER.FIELDS%20(DELIVERED-TO%20SUBJECT)"
kill $(jobs -p)
